<?php require 'includes/bootstrap.php';if(logged_in()){header('Location: account.php');exit;}$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){if(!csrf_ok())$errors[]='Некорректный запрос.';$email=trim($_POST['email']??'');$pass=$_POST['password']??'';if(!$email||!$pass)$errors[]='Введите email и пароль.';else{$s=$pdo->prepare('SELECT * FROM users WHERE email=?');$s->execute([$email]);$u=$s->fetch();if(!$u)$errors[]='Пользователь не найден.';elseif(!password_verify($pass,$u['password']))$errors[]='Неверный email или пароль.';else{$_SESSION['user']=['id'=>(int)$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>$u['role']];header('Location: account.php');exit;}}}$page_title='Вход';require 'includes/header.php'; ?>
<main class="auth-wrap"><form class="auth-card" method="post"><p class="eyebrow">С возвращением</p><h1>Войти</h1><?php foreach($errors as $x): ?><p class="error"><?=e($x)?></p><?php endforeach ?><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Email<input required type="email" name="email" value="<?=e($_POST['email']??'')?>"></label><label>Пароль<span class="password-field"><input required type="password" name="password"><button type="button" class="toggle-password" aria-label="Показать пароль">◉</button></span></label><button class="block">Войти</button><p>Впервые в NESTA? <a href="register.php">Создать аккаунт</a></p></form></main><?php require 'includes/footer.php'; ?>
